using System.Text.Json;
record Song(string Title,double Bpm,int Key);
class Program{
 static double Cost(Song a,Song b){int d=Math.Abs(a.Key-b.Key)%12;d=Math.Min(d,12-d);return Math.Abs(a.Bpm-b.Bpm)/5+d*2;}
 static List<Song> Plan(List<Song> songs){if(songs.Count==0)throw new ArgumentException("At least one song required");if(songs.Any(s=>s.Bpm<=0||!double.IsFinite(s.Bpm)||s.Key<0||s.Key>11||string.IsNullOrWhiteSpace(s.Title)))throw new ArgumentException("Valid title, positive BPM and circle-of-fifths key index 0–11 required");var remaining=songs.Skip(1).ToList();var result=new List<Song>{songs[0]};while(remaining.Count>0){var next=remaining.OrderBy(s=>Cost(result[^1],s)).ThenBy(s=>s.Title).First();result.Add(next);remaining.Remove(next);}return result;}
 static int Main(string[] args){try{if(args.Length==1&&args[0]=="--self-test"){var a=new Song("Opener",100,0);var b=new Song("Far",160,6);var c=new Song("Near",102,1);if(Plan(new(){a,b,c})[1]!=c||Cost(a,a)!=0)throw new Exception("Planning invariant");try{Plan(new(){new Song("bad",0,0)});return 1;}catch(ArgumentException){}Console.WriteLine("Opener, nearest-transition, and input validation checks passed");return 0;}if(args.Length!=1)throw new ArgumentException("Usage: dotnet run -- songs.json");var input=JsonSerializer.Deserialize<List<Song>>(File.ReadAllText(args[0]),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new Exception("Empty JSON");var plan=Plan(input);Console.WriteLine("SETLIST FLOW · first entry fixed as opener");for(int i=0;i<plan.Count;i++)Console.WriteLine($"{i+1,2}. {plan[i].Title,-24} {plan[i].Bpm,6:F1} BPM  key-index {plan[i].Key}  transition {(i==0?0:Cost(plan[i-1],plan[i])):F1}");Console.WriteLine("Greedy heuristic; key index means circle-of-fifths position, not pitch class.");return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
